//! Reference cases recorded from the TypeScript implementation.
//!
//! `ts_cases.json` (here and in `nodes/vec2/`) holds, per node type, input
//! spreads and the outputs the TS `compute` / `computeRaw` produced for
//! them — plain numbers, edge cases (NaN, ±Infinity, ±0) and non-number
//! values (undefined, null, booleans, strings, objects) — plus the
//! `dynamicInputs` port lists for a range of params. Values use the trace
//! encoding (`{"$u":1}`, `{"$num":"NaN"}`, plus `{"$num":"-0"}`); an
//! `{"$err":…}` output means the TS compute threw. They were generated by a
//! one-off vitest script that ran each registered TS node def over a seeded
//! pool of inputs; regenerate the same way if the TS nodes change.
//!
//! Known, deliberate gap: TS `===` on two *distinct* objects with equal
//! fields is false, but vec2 / colour values are unboxed here, so
//! `math/map` / `math/norm` / `math/smoothstep` treat equal-valued vec2 /
//! colour bounds as identical. The cases avoid that combination.

use crate::node::{EvalCtx, FrameCtx, NodeInit, ParamStore};
use crate::spec::{Catalogue, Params, PortKind, PortType};
use crate::value::{Spread, Value};
use serde_json::Value as J;

fn num_eq(a: f64, b: f64) -> bool {
    if a.is_nan() || b.is_nan() {
        return a.is_nan() && b.is_nan();
    }
    if a.is_infinite() || b.is_infinite() {
        return a == b;
    }
    let d = (a - b).abs();
    d <= 1e-12 || d <= 1e-9 * a.abs().max(b.abs())
}

/// Deep equality with float tolerance.
pub fn same_value(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Num(x), Value::Num(y)) => num_eq(*x, *y),
        (Value::Vec2(p), Value::Vec2(q)) => num_eq(p.x, q.x) && num_eq(p.y, q.y),
        (Value::Color(p), Value::Color(q)) => {
            num_eq(p.r, q.r) && num_eq(p.g, q.g) && num_eq(p.b, q.b) && num_eq(p.a, q.a)
        }
        (Value::List(x), Value::List(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|(a, b)| same_value(a, b))
        }
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len()
                && x.iter()
                    .all(|(k, v)| y.get(k).is_some_and(|w| same_value(v, w)))
        }
        _ => a.same(b),
    }
}

/// Like `Value::from_json`, but tagged numbers (`{"$num":"NaN"}`) also
/// count as numbers when recognising `{x,y}` / `{r,g,b,a}` shapes.
pub fn decode(j: &J) -> Value {
    match j {
        J::Array(items) => Value::list(items.iter().map(decode).collect()),
        J::Object(map) if !map.contains_key("$num") && !map.contains_key("$u") => {
            let fields: indexmap::IndexMap<String, Value> =
                map.iter().map(|(k, v)| (k.clone(), decode(v))).collect();
            let num = |k: &str| fields.get(k).and_then(Value::as_f64);
            if fields.len() == 2 {
                if let (Some(x), Some(y)) = (num("x"), num("y")) {
                    return Value::Vec2(crate::value::Vec2 { x, y });
                }
            }
            if fields.len() == 4 {
                if let (Some(r), Some(g), Some(b), Some(a)) =
                    (num("r"), num("g"), num("b"), num("a"))
                {
                    return Value::Color(crate::value::Color { r, g, b, a });
                }
            }
            Value::Object(std::sync::Arc::new(fields))
        }
        // JSON can't carry -0; the recorder tags it.
        J::Object(map) if map.get("$num").and_then(J::as_str) == Some("-0") => Value::Num(-0.0),
        other => Value::from_json(other),
    }
}

fn spread(j: &J) -> Spread {
    match decode(j) {
        Value::List(items) => items,
        other => panic!("expected a spread, got {other:?}"),
    }
}

/// Evaluate `ty` once with `inputs` (and node params) through its factory.
pub fn eval(ty: &str, params: &Params, inputs: &[Spread]) -> Result<Vec<Spread>, String> {
    let cat = Catalogue::builtin();
    let spec = cat.get(ty).unwrap_or_else(|| panic!("no spec for {ty}"));
    let resolved = cat.resolved_inputs(spec, params);
    let init = NodeInit {
        id: "t",
        spec,
        params,
        inputs: &resolved,
    };
    let factory = crate::nodes::factory(ty).unwrap_or_else(|| panic!("{ty} unimplemented"));
    let mut node = factory(&init);
    let frame = FrameCtx::default();
    let mut store = ParamStore::default();
    let mut cx = EvalCtx {
        node_id: "t",
        frame: &frame,
        tick_frame: &frame,
        params: &mut store,
        saved_params: params,
    };
    node.eval(inputs, &mut cx)
}

fn kind_name(k: PortKind) -> &'static str {
    match k {
        PortKind::Single => "single",
        PortKind::Spread => "spread",
        PortKind::Multi => "multi",
    }
}

/// Check every node type in a `ts_cases.json` document. Returns the number
/// of cases checked.
pub fn run_cases(doc: &str) -> usize {
    let doc: J = serde_json::from_str(doc).expect("ts_cases.json");
    let cat = Catalogue::builtin();
    let mut failures = Vec::new();
    let mut checked = 0;
    for (ty, entry) in doc.as_object().expect("object") {
        let adaptive_reducer = cat
            .get(ty)
            .is_some_and(|s| s.default_params.contains_key("slotCount"));
        for case in entry["cases"].as_array().expect("cases") {
            let inputs: Vec<Spread> = case["inputs"]
                .as_array()
                .expect("inputs")
                .iter()
                .map(spread)
                .collect();
            let mut params = Params::new();
            if adaptive_reducer {
                params.insert("slotCount".into(), J::from(inputs.len()));
            }
            let got = eval(ty, &params, &inputs);
            let want = &case["out"];
            checked += 1;
            let ok = match (&got, want.get("$err")) {
                (Err(_), Some(_)) => true,
                (Ok(outs), None) => {
                    let got = Value::list(outs.iter().cloned().map(Value::List).collect());
                    same_value(&got, &decode(want))
                }
                _ => false,
            };
            if !ok {
                failures.push(format!(
                    "{ty} inputs {}: rust {got:?} vs ts {want}",
                    case["inputs"]
                ));
            }
        }
        for d in entry["dynamic"].as_array().into_iter().flatten() {
            let params = d["params"].as_object().cloned().unwrap_or_default();
            let spec = cat.get(ty).expect("spec");
            assert!(cat.has_dynamic_impl(ty), "{ty}: no dynamic-inputs fn");
            let ports = cat.resolved_inputs(spec, &params);
            let want = d["ports"].as_array().expect("ports");
            checked += 1;
            let ok = ports.len() == want.len()
                && ports.iter().zip(want).all(|(p, w)| {
                    p.name == w["name"].as_str().unwrap_or_default()
                        && p.label.as_deref() == w["label"].as_str()
                        && Some(p.ty) == w["type"].as_str().and_then(PortType::parse)
                        && kind_name(p.kind) == w["kind"].as_str().unwrap_or_default()
                        && p.default
                            .as_ref()
                            .is_some_and(|v| same_value(v, &decode(&w["default"])))
                });
            if !ok {
                failures.push(format!(
                    "{ty} dynamicInputs({}): rust {ports:?} vs ts {}",
                    d["params"], d["ports"]
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {checked} TS reference cases differ:\n{}",
        failures.len(),
        failures
            .iter()
            .take(40)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
    checked
}

#[test]
fn matches_typescript_reference() {
    let n = run_cases(include_str!("ts_cases.json"));
    assert!(n > 1000, "only {n} cases");
}

#[test]
fn every_math_type_is_registered() {
    let cat = Catalogue::builtin();
    let missing: Vec<_> = cat
        .iter()
        .filter(|s| s.ty.starts_with("math/") && crate::nodes::factory(&s.ty).is_none())
        .map(|s| s.ty.clone())
        .collect();
    assert!(missing.is_empty(), "unimplemented: {missing:?}");
    let doc: J = serde_json::from_str(include_str!("ts_cases.json")).unwrap();
    // Native-only math nodes have no TypeScript cases (the op families
    // are checked against the nodes they supersede, in `family`).
    let native_only = ["math/expression", "math/math", "math/statistics"];
    let count = cat
        .iter()
        .filter(|s| s.ty.starts_with("math/") && !native_only.contains(&s.ty.as_str()))
        .count();
    assert_eq!(doc.as_object().unwrap().len(), count);
}

#[test]
fn median_sort_matches_v8_with_nan() {
    // `[...xs].sort((a, b) => a - b)` results from node (V8).
    let cases: [(&[f64], &[f64]); 5] = [
        (&[3.0, f64::NAN, 1.0, 2.0], &[3.0, f64::NAN, 1.0, 2.0]),
        (
            &[5.0, 1.0, f64::NAN, 4.0, 0.0, 2.0],
            &[0.0, 1.0, 2.0, 4.0, 5.0, f64::NAN],
        ),
        (&[f64::NAN, 2.0, 1.0], &[f64::NAN, 1.0, 2.0]),
        (
            &[2.0, 1.0, f64::NAN, 0.0, -1.0],
            &[-1.0, 0.0, 1.0, 2.0, f64::NAN],
        ),
        (
            &[4.0, 3.0, f64::NAN, 2.0, 1.0, f64::NAN, 0.0],
            &[0.0, 1.0, 2.0, 3.0, 4.0, f64::NAN, f64::NAN],
        ),
    ];
    for (input, want) in cases {
        let mut xs = input.to_vec();
        super::aggregate::sort_by_difference(&mut xs);
        let same = xs
            .iter()
            .zip(want)
            .all(|(a, b)| a == b || (a.is_nan() && b.is_nan()));
        assert!(same, "{input:?}: got {xs:?}, want {want:?}");
    }
}

#[test]
fn clamp_wrap_and_map_adapt_to_vec2() {
    use crate::nodes::value::harness::node;
    use crate::value::Vec2;
    use serde_json::json;
    let v = |x, y| Value::Vec2(Vec2 { x, y });
    let n = Value::Num;
    let point = |out: Vec<Value>| match out[0] {
        Value::Vec2(p) => (p.x, p.y),
        ref other => panic!("not a vec2: {other:?}"),
    };
    let vec2 = json!({ "valueType": "vec2" });
    // Clamp a point into a box (per component), or by one number.
    let mut c = node("math/clamp", vec2.clone());
    let box_ = [v(0.0, 0.0), v(10.0, 20.0)];
    assert_eq!(
        point(c.eval1(&[v(-5.0, 50.0), box_[0].clone(), box_[1].clone()])),
        (0.0, 20.0)
    );
    assert_eq!(point(c.eval1(&[v(-5.0, 5.0), n(0.0), n(1.0)])), (0.0, 1.0));
    // Wrap a point around a box.
    let mut w = node("math/wrap", vec2.clone());
    assert_eq!(
        point(w.eval1(&[v(-1.0, 25.0), box_[0].clone(), box_[1].clone()])),
        (9.0, 5.0)
    );
    // Map per component.
    let mut m = node("math/map", vec2.clone());
    let got = point(m.eval1(&[v(0.5, 0.25), n(0.0), n(1.0), v(0.0, 100.0), v(10.0, 200.0)]));
    assert_eq!(got, (5.0, 125.0));
    // The pins follow `valueType`, like Math's.
    let cat = Catalogue::builtin();
    let pins = |ty: &str, p: serde_json::Value| -> Vec<PortType> {
        cat.resolved_inputs(cat.get(ty).unwrap(), p.as_object().unwrap())
            .into_iter()
            .map(|p| p.ty)
            .collect()
    };
    assert_eq!(pins("math/clamp", vec2.clone()), [PortType::Vec2; 3]);
    assert_eq!(pins("math/map", vec2), [PortType::Vec2; 5]);
    assert_eq!(
        pins("math/wrap", json!({ "valueType": "number" })),
        [PortType::Number; 3]
    );
    // Unlatched (and old files, which have no `valueType`): numbers as
    // before — a vec2 reaching the node computes NaN, as it always did.
    let mut c = node("math/clamp", json!({}));
    assert!(c.eval1(&[v(1.0, 2.0), n(0.0), n(1.0)])[0]
        .as_f64()
        .unwrap()
        .is_nan());
    assert_eq!(c.eval1(&[n(5.0), n(0.0), n(1.0)])[0].as_f64(), Some(1.0));
}

#[test]
fn smoothstep_window_rises_and_falls() {
    use crate::nodes::value::harness::{node, Harness};
    use serde_json::json;
    let n = Value::Num;
    let mut s = node("math/smoothstep", json!({ "mode": "window" }));
    let at = |s: &mut Harness, x: f64| {
        s.eval1(&[n(0.0), n(1.0), n(3.0), n(4.0), n(x)])[0]
            .as_f64()
            .unwrap()
    };
    let table = [
        (-1.0, 0.0),
        (0.0, 0.0),
        (0.5, 0.5),
        (1.0, 1.0),
        (2.0, 1.0),
        (3.5, 0.5),
        (4.0, 0.0),
        (9.0, 0.0),
    ];
    for (x, want) in table {
        assert!((at(&mut s, x) - want).abs() < 1e-12, "{x}");
    }
    // The classic mode (and old files): edge0, edge1, x as before.
    let mut s = node("math/smoothstep", json!({}));
    assert_eq!(s.eval1(&[n(0.0), n(2.0), n(1.0)])[0].as_f64(), Some(0.5));
    let cat = Catalogue::builtin();
    let spec = cat.get("math/smoothstep").unwrap();
    let names = |p: serde_json::Value| -> Vec<String> {
        cat.resolved_inputs(spec, p.as_object().unwrap())
            .into_iter()
            .map(|p| p.name)
            .collect()
    };
    assert_eq!(names(json!({})), ["edge0", "edge1", "x"]);
    assert_eq!(
        names(json!({ "mode": "window" })),
        ["edge0", "edge1", "edge2", "edge3", "x"]
    );
}
